<?php
namespace App\Http\Controllers; use App\Models\{Order,Shipment}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class OrderController extends Controller {public function index(){return view('admin.orders.index',['orders'=>Order::with('user')->latest('order_date')->paginate(20)]);}public function show(Order $order){$order->load(['user','items.sku.product','payment','shipment','coupon']);return view('admin.orders.show',compact('order'));}public function update(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:Pending,Processing,Shipped,Delivered,Cancelled']);$order->update(['status'=>$d['status']]);if($d['status']==='Shipped'&&!$order->shipment){Shipment::create(['order_id'=>$order->order_id,'shipping_provider'=>'Manual','status'=>'In Transit']);}if($d['status']==='Delivered'&&$order->shipment)$order->shipment->update(['status'=>'Delivered']);return back()->with('success','Order status updated.');}}
